	private static long findMin(long l, long r, long d) {
		if (d < Math.min(l, r)) {
			return d;
		}
		if (Math.max(l, r) % d == 0) {
			return Math.max(l, r) + d;
		}
		return d + Math.max(l, r) - Math.max(l, r) % d;

	}

