	long power(long x, long y, long p){  
        long res = 1;      
        x = x % p;  
        while (y > 0) 
        { 
            if((y & 1)==1) 
                res = (res * x) % p; 
            y = y >> 1;  
            x = (x * x) % p;  
        } 
        return res; 
    }

	long ncr(int n, int r, long p){  
        long C[]=new long[r+1]; 
        C[0] = 1; 
        for (int i = 1; i <= n; i++) 
        { 
            for (int j = Math.min(i, r); j > 0; j--) 
                C[j] = (C[j] + C[j-1])%p; 
        } 
        return C[r]; 
    }

	long gcd(long a,long b){
		if(b%a==0){return a;}
		else{return gcd(b%a,a);}
