def sequential_max_diff(seq):
    unlagged_seq = seq[:-1]
    lagged_seq = seq[1:]
    maxd = 0
    for pair in zip(unlagged_seq, lagged_seq):
        diff = abs(pair[0]-pair[1])

        if diff > maxd:
            maxd= diff
    return maxd

