  static class AMinimumInteger {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int q = in.readInt();
      for (int i = 0; i < q; ++i) {

        int l = in.readInt(), r = in.readInt(), d = in.readInt();

