class Graph {
 public:
  int V;
  vector<int> v[25];
  bool visited[25] = {0};
  queue<int> q;
  Graph(int V) { this->V = V; }
  void addEdge(int a, int b) {
    v[a].push_back(b);
    v[b].push_back(a);
  }
  void dfs(int x) {
    if (visited[x] == 0) {
      visited[x] = 1;
      for (int u : v[x]) {
        dfs(u);
      }
    }
  }
  void bfs(int n, int x) {
    visited[x] = 1;
    q.push(x);
    while (!q.empty()) {
      int s = q.front();
      q.pop();
      for (int u : v[s]) {
        if (visited[u] == 1) continue;
        visited[u] = 1;
        q.push(u);
      }
    }
  }
  int connectedcomponents(int n) {
    int ans = 0;
    for (int i = 1; i < n + 1; i++) {
      if (!visited[i]) {
        ans++;
        dfs(i);
      }
    }
    return ans;
  }
};
