 public static class SegmentTree {		// 1-based DS, OOP

		int N; 			//the number of elements in the array as a power of 2 (i.e. after padding)
		boolean[] array, sTree, lazy;

		SegmentTree(boolean[] in)		
		{
			array = in; N = in.length - 1;
			sTree = new boolean[N<<1];		//no. of nodes = 2*N - 1, we add one to cross out index zero
			lazy = new boolean[N<<1];
//			build(1,1,N);
		}

