//		

		void update_point(int index, boolean val)			// O(log n)
		{
			index += N - 1;				
			sTree[index] |= val;			
			while(index>1)				
			{
				index >>= 1;
				sTree[index] = sTree[index<<1] || sTree[index<<1|1];		
			}
		}


		void update_range(int i, int j, boolean val)		// O(log n) 
		{
			update_range(1,1,N,i,j,val);
		}

		void update_range(int node, int b, int e, int i, int j, boolean val)
		{
			if(i > e || j < b)		
				return;
			if(b >= i && e <= j)		
			{
				sTree[node] |= val;			
				lazy[node] |= val;				
			}							
			else		
			{
				int mid = b + e >> 1;
				propagate(node, b, mid, e);
				update_range(node<<1,b,mid,i,j,val);
				update_range(node<<1|1,mid+1,e,i,j,val);
				sTree[node] = sTree[node<<1] | sTree[node<<1|1];		
			}

		}
		void propagate(int node, int b, int mid, int e)		
		{
			lazy[node<<1] |= lazy[node];
			lazy[node<<1|1] |= lazy[node];
			sTree[node<<1] |= lazy[node];		
			sTree[node<<1|1] |= lazy[node];		
			lazy[node] = false;
		}

