def minInt(x):
	if len(x) < 3:
		return -1
	li = int(x[0])
	ri = int(x[1])
	di = int(x[2])
	if di < li:
		return di
	elif di >= li and di < ri:
		return int(math.ceil(ri/di+1)*di)
	else:
		return int(math.ceil((ri-1)/di+1)*di)

