        int t = in.nextInt();

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < t; i++) {
            long a = in.nextLong(), b = in.nextLong(), n = in.nextLong();

            if (n < a || n > b) {
                sb.append(n).append("\n");
            } else {
                if (((a + b) % n) == 0) {
                    sb.append(a + b).append("\n");
                } else {
                    long cp = n;
                    while (n <= b || (n % cp) != 0) {
                        n *= 2;
                    }
                    sb.append(n).append("\n");
                }
            }
        }

        System.out.print(sb);
    }
}

class FastReader {

    BufferedReader br;
    StringTokenizer st;

    public FastReader() {
        br = new BufferedReader(new InputStreamReader(System.in));
    }

    String next() {
        while (st == null || !st.hasMoreElements()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        return st.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    double nextDouble() {
        return Double.parseDouble(next());
    }

    String nextLine() {
        String str = "";
        try {
            str = br.readLine();
        } catch (IOException e) {
            e.printStackTrace();
        }
        return str;
    }
}
