long long mod_expo(long long n, long long exp, long long p = MOD) {
  long long res = 1;
  while (exp > 0) {
    if (exp & 1) {
      res = ((res % p) * (n % p)) % p;
      exp--;
    };
    n = ((n % p) * (n % p)) % p;
    exp >>= 1;
  }
  return res;
}
