        Scanner sc = new Scanner(new InputStreamReader(System.in));
        int t = sc.nextInt();
        Map<String, Long> map = new HashMap<>();
        while (t-- > 0) {
            long l = sc.nextLong();
            long r = sc.nextLong();
            long d = sc.nextLong();
            long ans = 0;
            String key = String.format("%d,%d,%d", l, r, d);
            if (map.containsKey(key)) {
                ans = map.get(key);
            } else {
                if (d == 1) {
                    if (l > 1)
                        ans = 1;
                    else if (r < Long.MAX_VALUE)
                        ans = r + 1;
                } else {
                    for (long i = 1; i < Integer.MAX_VALUE / d; i++) {
                        if (i * d < l || i * d > r) {
                            ans = i * d;
                            break;
                        }
                    }
                }
                map.put(key, ans);
            }
            System.out.println(ans);
        }
    }
}
