        out.close();
    }

    static class AMinimumInteger {
        public void solve(int testNumber, inclass in, PrintWriter out) {
            int q = in.nextInt();
            label:
            while (q-- > 0) {
                int l = in.nextInt(), r = in.nextInt(), d = in.nextInt();
                int left = l - (l % d);
                if (d == 1) out.println(1);
                if (d == 1) continue label;
                if (l % d == 0) {
                    left = l - (d);
                    if (left > 0) {
                        out.println(left);
                        continue label;
                    }
                } else {
                    if (left > 0) {
                        out.println(left);
                        continue label;
                    }
                }
                long right = r - (r % d);
                right = right + (long) (d);
                out.println(right);
            }
        }

    }

    static class inclass {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private inclass.SpaceCharFilter filter;

        public inclass(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
